#!/usr/bin/env bash
set -euo pipefail

bootstrap_file="${1:-.staging-bootstrap.env}"
dotenv_file="${2:-.env}"
repository="${GITHUB_REPOSITORY:-alazark777/booking-assist}"

if [[ ! -f "$bootstrap_file" ]]; then
  printf 'Bootstrap output file not found: %s\nRun infra/bootstrap/bootstrap.sh first.\n' "$bootstrap_file" >&2
  exit 1
fi

command -v gh >/dev/null || {
  printf 'Missing required command: gh\n' >&2
  exit 1
}

set -a
# This file is generated by bootstrap.sh and is protected with mode 600.
# shellcheck disable=SC1090
source "$bootstrap_file"
set +a

required_variables=(
  AZURE_CLIENT_ID_APPLY
  AZURE_CLIENT_ID_PLAN
  AZURE_SUBSCRIPTION_ID
  AZURE_TENANT_ID
  TF_STATE_RESOURCE_GROUP
  TF_STATE_STORAGE_ACCOUNT
  TF_STATE_CONTAINER
  AZURE_RESOURCE_GROUP
)

for variable_name in "${required_variables[@]}"; do
  if [[ -z "${!variable_name:-}" ]]; then
    printf 'Missing %s in %s\n' "$variable_name" "$bootstrap_file" >&2
    exit 1
  fi
done

gh api --method PUT "repos/${repository}/environments/staging" >/dev/null

for variable_name in "${required_variables[@]}"; do
  gh variable set "$variable_name" \
    --repo "$repository" \
    --env staging \
    --body "${!variable_name}" \
    >/dev/null
done

google_api_key="${GOOGLE_API_KEY:-}"
if [[ -z "$google_api_key" && -f "$dotenv_file" ]]; then
  google_api_key="$(awk -F= '/^GOOGLE_API_KEY=/{sub(/^[^=]*=/, ""); print; exit}' "$dotenv_file")"
fi
google_api_key="${google_api_key:-REPLACE_WITH_GOOGLE_API_KEY}"
printf '%s' "$google_api_key" | gh secret set GOOGLE_API_KEY --repo "$repository" --env staging >/dev/null

service_credentials="${SERVICE_CREDENTIALS:-alice-token=customer-a,bob-token=customer-b}"
printf '%s' "$service_credentials" | gh secret set SERVICE_CREDENTIALS --repo "$repository" --env staging >/dev/null

printf 'GitHub staging environment configured for %s.\n' "$repository"
if [[ "$google_api_key" == "REPLACE_WITH_GOOGLE_API_KEY" ]]; then
  printf 'GOOGLE_API_KEY remains a placeholder; replace it before deploying.\n'
else
  printf 'GOOGLE_API_KEY was loaded from the local environment without being printed.\n'
fi
